CREATE TABLE beneficiaries (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, destination_account_id UUID NOT NULL, nickname VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL, available_at TIMESTAMPTZ NOT NULL, CONSTRAINT uk_beneficiary_owner_destination UNIQUE(owner_user_id,destination_account_id)); CREATE INDEX idx_beneficiaries_owner ON beneficiaries(owner_user_id,created_at DESC);